import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Design tokens
  const colors = {
    background: new THREE.Color('#0b0b10'),
    surface: new THREE.Color('#14141a'),
    ink: new THREE.Color('#16161d'),
    paper: new THREE.Color('#e8ecf2'),
    accent: new THREE.Color('#ff2a38'),
  };

  // Constants
  const CARD_WIDTH = 1.6;
  const CARD_HEIGHT = 1.0;
  const CARD_PITCH = 1.85;
  const NUM_CARDS = 5;
  const STRIP_ROTATION_Y = -18 * Math.PI / 180;
  const COUNTER_ROTATION_Y = 18 * Math.PI / 180;

  // Load base texture
  const baseTexture = ctx.textureLoader.load('/prism-mock/home/nodes/parallax-stack.png');

  // Create filmstrip group (rotated -18° on y)
  const filmstrip = new THREE.Group();
  filmstrip.rotation.y = STRIP_ROTATION_Y;
  group.add(filmstrip);

  // Create 5 cards
  const cards = [];
  for (let i = 0; i < NUM_CARDS; i++) {
    const xPos = (i - 2) * CARD_PITCH;

    // Card geometry and material
    const cardGeom = new THREE.PlaneGeometry(CARD_WIDTH, CARD_HEIGHT);
    const cardMat = new THREE.MeshPhysicalMaterial({
      map: baseTexture,
      roughness: 0.55,
      metalness: 0.2,
      clearcoat: 0.15,
      clearcoatRoughness: 0.1,
      transparent: true,
    });

    const cardMesh = new THREE.Mesh(cardGeom, cardMat);
    cardMesh.position.x = xPos;
    cardMesh.userData.cardIndex = i;

    // Add ink bevel frame
    const bevelGeom = new THREE.EdgesGeometry(cardGeom);
    const bevelMat = new THREE.LineBasicMaterial({
      color: colors.ink,
      linewidth: 2,
    });
    const bevelLines = new THREE.LineSegments(bevelGeom, bevelMat);
    bevelLines.scale.set(1.05, 1.05, 1);
    cardMesh.add(bevelLines);

    filmstrip.add(cardMesh);
    cards.push({ mesh: cardMesh, material: cardMat });
  }

  // Add headline text
  const headlineText = ctx.fontAtlas.createText('The collection', {
    fontSize: 0.34,
    fontFamily: 'Lora',
    fontWeight: 600,
    color: colors.paper,
    letterSpacing: -0.005,
  });
  headlineText.position.set(-2.6, 1.5, 0);
  group.add(headlineText);

  // Add body text
  const bodyText = ctx.fontAtlas.createText('Five calibres. One discipline.', {
    fontSize: 0.13,
    fontFamily: 'JetBrains Mono',
    fontWeight: 400,
    color: colors.paper,
  });
  bodyText.position.set(-2.6, -1.5, 0);
  group.add(bodyText);

  // Add card captions
  const captions = [
    'NA-01 MERIDIAN',
    'NA-02 NOCTURNE',
    'NA-03 SIGNAL',
    'NA-04 VANTAGE',
    'NA-05 ARCHIVE',
  ];

  for (let i = 0; i < NUM_CARDS; i++) {
    const captionText = ctx.fontAtlas.createText(captions[i], {
      fontSize: 0.09,
      fontFamily: 'JetBrains Mono',
      fontWeight: 700,
      color: colors.paper,
      letterSpacing: 0.08,
    });
    const xPos = (i - 2) * CARD_PITCH;
    captionText.position.set(xPos, -0.65, 0.01);
    group.add(captionText);
  }

  // Add focused card underline bar
  const underlineGeom = new THREE.PlaneGeometry(CARD_WIDTH, 0.035);
  const underlineMat = new THREE.MeshStandardMaterial({
    color: colors.accent,
    emissive: colors.accent,
    emissiveIntensity: 1.3,
    metalness: 0.3,
    roughness: 0.4,
  });
  const underline = new THREE.Mesh(underlineGeom, underlineMat);
  underline.position.set(0, -0.55, 0.01);
  group.add(underline);

  // State
  group.userData.scrollOffset = 0;
  group.userData.isSnapping = false;
  group.userData.timelines = [];

  // Update card states based on scroll offset
  const updateCardStates = () => {
    for (let i = 0; i < NUM_CARDS; i++) {
      const card = cards[i];
      const distance = Math.abs(card.mesh.position.x - group.userData.scrollOffset);

      if (distance < 0.2) {
        // Focused card
        card.mesh.rotation.y = COUNTER_ROTATION_Y;
        card.mesh.scale.set(1.0, 1.0, 1.0);
        card.material.opacity = 1.0;
      } else {
        // Unfocused cards
        card.mesh.rotation.y = 0;
        card.mesh.scale.set(0.92, 0.92, 1.0);
        const opacityFade = Math.max(0.55, 1.0 - (distance / (CARD_PITCH * 2)) * 0.45);
        card.material.opacity = opacityFade;
      }
    }
    filmstrip.position.x = group.userData.scrollOffset * 0.5;
  };

  // Snap to nearest card
  let snapTimeoutId;
  const snapToNearest = () => {
    if (group.userData.isSnapping) return;
    group.userData.isSnapping = true;

    const nearestIndex = Math.round(group.userData.scrollOffset / CARD_PITCH);
    const targetOffset = nearestIndex * CARD_PITCH;

    const tl = gsap.to(group.userData, {
      scrollOffset: targetOffset,
      duration: 0.9,
      ease: 'power4.out',
      onUpdate: updateCardStates,
      onComplete: () => {
        group.userData.isSnapping = false;
      },
    });

    group.userData.timelines.push(tl);
  };

  // Scroll event handler
  const handleScroll = (delta) => {
    group.userData.scrollOffset += delta * 0.0008;
    gsap.killTweensOf(group.userData);
    updateCardStates();

    if (snapTimeoutId) clearTimeout(snapTimeoutId);
    snapTimeoutId = setTimeout(snapToNearest, 300);
  };

  // Attach handler to userData
  group.userData.handlers = {
    scroll: handleScroll,
  };

  // Apply parallax-scroll cinematic primitive
  ctx.primitives.parallaxScroll(group, { intensity: 0.5 });

  // Cleanup function
  group.userData.cleanup = () => {
    if (snapTimeoutId) clearTimeout(snapTimeoutId);
    gsap.killTweensOf(group.userData);
    group.userData.timelines.forEach(tl => tl.kill());

    baseTexture.dispose();
    cards.forEach(card => {
      card.mesh.geometry.dispose();
      card.material.dispose();
    });
    underlineGeom.dispose();
    underlineMat.dispose();
  };

  return group;
}
